Corollary kHighMemBeg_le : forall h (a : word) nZ Y,
  0 < nZ -> nZ mod page_size = 0 ->
  bv_unsigned a mod page_size = 0 ->
  Y mod page_size = 0 -> Y <= bv_unsigned (vm_mmap_base h) ->
  kHighMemBeg + 2 * nZ <= Y ->
  ledger_split (vm_reserved h ++ vm_maps h) kHighMemBeg Y ->
